// newInput builds the insert a Batch queues for in under parent, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLInventoryRepository) newInput(parent string, in *inventoryv1.Inventory) (inventoriesql.CreateInput, *inventoryv1.Inventory, error) {
	var ci inventoriesql.CreateInput
	parentIDs, err := repox.SplitName(parent, "hotels", "roomTypes")
	if err != nil {
		return ci, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "hotels", "roomTypes", "inventories")
		if err != nil {
			return ci, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return ci, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*inventoryv1.Inventory)
	in.Name = FormatInventoryName(parentIDs[0], parentIDs[1], id)
	id = rowID // keyed as Create keys it
	ci = inventoryToCreateInput(in)
	ci.Id = id
	ci.HotelId = parentIDs[0]
	ci.RoomTypeId = parentIDs[1]
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

