// UpdateOutputOnly persists the server-owned fields of in that paths names.
// When in.Etag is set the write is guarded server-side, as in Update.
func (r *GraphQLInventoryRepository) UpdateOutputOnly(ctx context.Context, in *inventoryv1.Inventory, paths []string) (*inventoryv1.Inventory, error) {
	if len(paths) == 0 {
		return nil, fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	id, err := r.rowID(ctx, in.GetName())
	if err != nil {
		return nil, err
	}
	patch := inventoryToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.Inventory.Inventories.UpdateIfMatch(ctx, id, patch, inventoriesql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.Inventory.Inventories.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. The update time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GraphQLInventoryRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "hotels", "roomTypes", "inventories"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.Inventory.Inventories.UpdateIfMatch(ctx, id, r.deletePatch(), inventoriesql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLInventoryRepository) deletePatch() inventoriesql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := inventoriesql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.UpdateTime = graphql.Value(now) // the delete is the record's latest write
	if r.Retention > 0 {
		patch.ExpireTime = graphql.Value(at.Add(r.Retention).Format(time.RFC3339Nano))
	}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLInventoryRepository) Undelete(ctx context.Context, name string) (*inventoryv1.Inventory, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := inventoriesql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.UpdateTime = graphql.Value(time.Now().UTC().Format(time.RFC3339Nano))
	patch.ExpireTime = graphql.Null[string]()
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.Inventory.Inventories.UpdateIfMatch(ctx, id, patch, inventoriesql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLInventoryRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "hotels", "roomTypes", "inventories"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: when askReferrers, a
// referrer in another database or service (r.Refs), and, caught from the
// database's own refusal, a row holding a foreign key to it. A purge never
// fails, and never cascades, because of a referrer. repox.ErrNotFound when
// there is no such row.
func (r *GraphQLInventoryRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/Inventory", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLInventoryRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLInventoryRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.Inventory.Inventories.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	dtx := r.Svc.Mutation.Tx()
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].OffSellId); id != "" {
			got9, err := r.Svc.Query.Inventory.OffSells.Get(ctx, id)
			if err != nil {
				return mapGraphQLErr(err)
			}
			if got9 != nil {
				dtx.Add(r.Svc.Mutation.Inventory.OffSells.DeleteOp(got9.Id, new(offsellsql.DeleteInventoryOffSellsByIdResponse)))
				if id := repox.Deref(got9.OffSellValueId); id != "" {
					got10, err := r.Svc.Query.Inventory.Decimals.Get(ctx, id)
					if err != nil {
						return mapGraphQLErr(err)
					}
					if got10 != nil {
						dtx.Add(r.Svc.Mutation.Inventory.Decimals.DeleteOp(got10.Id, new(decimalsql.DeleteInventoryDecimalsByIdResponse)))
					}
				}
			}
		}
	}
	for i := range resp.Returning {
		_ = repox.Deref(resp.Returning[i].UniqueIdId)
	}
	{
		rows37, err := r.Svc.Query.Inventory.InvCounts.List(ctx, invcountsql.List().Where(invcountsql.InventoryId.Eq(id)))
		if err != nil {
			return mapGraphQLErr(err)
		}
		for i := range rows37 {
			if id := rows37[i].Id; id != "" {
				got38, err := r.Svc.Query.Inventory.InvCounts.Get(ctx, id)
				if err != nil {
					return mapGraphQLErr(err)
				}
				if got38 != nil {
					dtx.Add(r.Svc.Mutation.Inventory.InvCounts.DeleteOp(got38.Id, new(invcountsql.DeleteInventoryInvCountsByIdResponse)))
					if id := repox.Deref(got38.InvBlockCutoffId); id != "" {
						got39, err := r.Svc.Query.Inventory.InvBlockCutoffs.Get(ctx, id)
						if err != nil {
							return mapGraphQLErr(err)
						}
						if got39 != nil {
							dtx.Add(r.Svc.Mutation.Inventory.InvBlockCutoffs.DeleteOp(got39.Id, new(invblockcutoffsql.DeleteInventoryInvBlockCutoffsByIdResponse)))
							if id := repox.Deref(got39.AbsoluteCutoffId); id != "" {
								got40, err := r.Svc.Query.Inventory.DateOrTimeOrDateTimes.Get(ctx, id)
								if err != nil {
									return mapGraphQLErr(err)
								}
								if got40 != nil {
									dtx.Add(r.Svc.Mutation.Inventory.DateOrTimeOrDateTimes.DeleteOp(got40.Id, new(dateortimeordatetimesql.DeleteInventoryDateOrTimeOrDateTimesByIdResponse)))
									if id := repox.Deref(got40.DayId); id != "" {
										got41, err := r.Svc.Query.Inventory.Dates.Get(ctx, id)
										if err != nil {
											return mapGraphQLErr(err)
										}
										if got41 != nil {
											dtx.Add(r.Svc.Mutation.Inventory.Dates.DeleteOp(got41.Id, new(datesql.DeleteInventoryDatesByIdResponse)))
										}
									}
									if id := repox.Deref(got40.ClockId); id != "" {
										got42, err := r.Svc.Query.Inventory.TimeOfDays.Get(ctx, id)
										if err != nil {
											return mapGraphQLErr(err)
										}
										if got42 != nil {
											dtx.Add(r.Svc.Mutation.Inventory.TimeOfDays.DeleteOp(got42.Id, new(timeofdaysql.DeleteInventoryTimeOfDaysByIdResponse)))
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}
	if err := dtx.Commit(ctx); err != nil {
		return mapGraphQLErr(err)
	}
	return nil
}

